<script setup lang="ts">
import{computed,nextTick,ref,useId}from'vue';import MValueBridge from './MValueBridge.vue';import type{MInputOTPProps}from'./types';import{useReferenceConfig}from'./locale';
import{useDraftReset}from'./shared';
const props=withDefaults(defineProps<MInputOTPProps>(),{length:6,type:'numeric',masked:false});const emit=defineEmits<{ 'update:modelValue':[value:string];complete:[value:string] }>();const{t}=useReferenceConfig();const root=ref<HTMLElement>(),identity=`ui-otp-${useId()}`;const count=computed(()=>Number.isInteger(props.length)&&props.length>0?Math.min(32,props.length):6);const chars=computed(()=>[...props.modelValue]);const validChars=(text:string)=>props.type==='numeric'?text.replace(/\D/g,''):text.replace(/\s/g,'');
function controls(){return [...root.value?.querySelectorAll<HTMLInputElement>('.ui-ri-otp__digit')||[]];}
function sync(){controls().forEach((input,index)=>input.value=chars.value[index]||'');}
function focus(index:number){controls()[Math.max(0,Math.min(count.value-1,index))]?.focus();controls()[Math.max(0,Math.min(count.value-1,index))]?.select();}
function write(index:number,text:string){if(props.disabled||props.readonly)return;index=Math.min(index,chars.value.length);const incoming=[...validChars(text)];const next=[...chars.value];if(!incoming.length)next.splice(index,1);else next.splice(index,incoming.length,...incoming);const value=next.slice(0,count.value).join('');emit('update:modelValue',value);if(value.length===count.value)emit('complete',value);void nextTick(()=>{sync();focus(Math.min(index+incoming.length,count.value-1));});}
function key(event:KeyboardEvent,index:number){if(event.isComposing)return;if(event.key==='Backspace'){event.preventDefault();if(chars.value[index])write(index,'');else if(index>0){write(index-1,'');focus(index-1);}}else if(event.key==='Delete'){event.preventDefault();write(index,'');}else if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();focus(index+(event.key==='ArrowLeft'?-1:1));}else if(event.key==='Home'){event.preventDefault();focus(0);}else if(event.key==='End'){event.preventDefault();focus(count.value-1);}}
function paste(event:ClipboardEvent,index:number){if(props.disabled||props.readonly)return;event.preventDefault();write(index,event.clipboardData?.getData('text')||'');}
const error=computed(()=>props.modelValue&&(![...props.modelValue].every(char=>validChars(char)===char)||chars.value.length!==count.value)?t('otp.incomplete','请填写完整有效的验证码。'):'');
useDraftReset(root,sync);
</script>
<template><div ref="root" class="ui-ri" role="group" :aria-labelledby="identity"><span :id="identity" class="ui-ri__label">{{label}}</span><div class="ui-ri-otp"><input v-for="index in count" :key="index" class="ui-ri__control ui-ri-otp__digit" :value="chars[index-1]||''" :aria-label="`${label} ${index} / ${count}`" :type="masked?'password':'text'" :inputmode="type==='numeric'?'numeric':'text'" :autocomplete="index===1?'one-time-code':'off'" :form="form" :disabled="disabled" :readonly="readonly" @focus="($event.target as HTMLInputElement).select()" @input="!($event as InputEvent).isComposing&&write(index-1,($event.target as HTMLInputElement).value)" @compositionend="write(index-1,($event.target as HTMLInputElement).value)" @keydown="key($event,index-1)" @paste="paste($event,index-1)"></div><MValueBridge v-bind="props" :values="modelValue?[modelValue]:[]" :error="error"/></div></template>
<style scoped>.ui-ri-otp{display:flex;flex-wrap:wrap;gap:8px}.ui-ri-otp__digit{width:44px;min-height:44px;padding:8px;text-align:center;font:20px/1.3 var(--ui-font-family-mono)}</style>
